#!/usr/bin/env python3
"""Minimal MCP streamable-HTTP client for the credit-desk server."""
import json
import urllib.request

URL = "http://mcp-server:8000/mcp"
SESSION = None


def _post(payload, extra_headers=None):
    global SESSION
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json, text/event-stream",
    }
    if SESSION:
        headers["mcp-session-id"] = SESSION
    if extra_headers:
        headers.update(extra_headers)
    req = urllib.request.Request(
        URL, data=json.dumps(payload).encode(), headers=headers, method="POST"
    )
    with urllib.request.urlopen(req, timeout=600) as r:
        sid = r.headers.get("mcp-session-id")
        if sid:
            SESSION = sid
        raw = r.read().decode()
    for line in raw.splitlines():
        if line.startswith("data: "):
            return json.loads(line[6:])
    if raw.strip():
        return json.loads(raw)
    return None


def initialize():
    global SESSION
    r = _post({
        "jsonrpc": "2.0", "id": 1, "method": "initialize",
        "params": {
            "protocolVersion": "2024-11-05", "capabilities": {},
            "clientInfo": {"name": "underwriter", "version": "1"},
        },
    })
    _post({"jsonrpc": "2.0", "method": "notifications/initialized", "params": {}})
    return r


def call(name, args, timeout=600):
    return _post({
        "jsonrpc": "2.0", "id": 2, "method": "tools/call",
        "params": {"name": name, "arguments": args},
    })


def tool(name, args):
    """Call a tool and return the parsed text content."""
    r = call(name, args)
    if r is None:
        return None
    if "error" in r:
        return {"error": r["error"]}
    out = []
    for c in r["result"].get("content", []):
        if c.get("type") == "text":
            t = c["text"]
            try:
                out.append(json.loads(t))
            except Exception:
                out.append(t)
    sc = r["result"].get("structuredContent")
    if sc is not None:
        return sc
    if len(out) == 1:
        return out[0]
    return out


if __name__ == "__main__":
    initialize()
    r = call("tools/list", {})
    for t in r["result"]["tools"]:
        print(json.dumps(t, indent=2))

#!/usr/bin/env python3
"""Fetch sandbox draws and cache to /tmp/opencode/data.json"""
import json
import os
import sys

sys.path.insert(0, "/tmp/opencode")
import mcp

CACHE = "/tmp/opencode/data.json"
BANDS = [560, 630, 690, 750, 820]


def load():
    if os.path.exists(CACHE):
        with open(CACHE) as f:
            return json.load(f)
    return {}


def save(d):
    with open(CACHE, "w") as f:
        json.dump(d, f)


def fetch(check, segment, n):
    d = load()
    key = f"{check}|{segment}"
    d.setdefault(key, [])
    have = len(d[key])
    todo = n - have
    while todo > 0:
        take = min(50, todo)
        r = mcp.tool("simulate", {"segment": segment, "check": check, "n": take})
        if isinstance(r, dict) and "error" in r:
            print("ERR", r)
            break
        vals = None
        if isinstance(r, dict):
            for k in ("scores", "draws", "values", "samples", "result"):
                if k in r:
                    vals = r[k]
                    break
            if vals is None:
                print("unexpected keys", list(r.keys()))
                vals = None
        elif isinstance(r, list):
            vals = r
        if vals is None:
            print("BAD RESPONSE", r)
            break
        d[key].extend(vals)
        todo -= take
        save(d)
    save(d)
    return d


if __name__ == "__main__":
    check = sys.argv[1]
    n = int(sys.argv[2])
    d = load()
    for seg in ["S1", "S2", "S3", "S4", "S5", "S6"]:
        fetch(check, seg, n)
    print(json.dumps(mcp.tool("status", {}), indent=1))
    d = load()
    for k in sorted(d):
        v = d[k]
        print(k, "n=", len(v), "mean=%.2f" % (sum(v) / len(v)),
              "min=%.1f" % min(v), "max=%.1f" % max(v))

#!/usr/bin/env python3
"""EM fit: per-cell locations + per-check-kind GMM noise model.
Outputs band probability tables P(band | segment, check)."""
import json
import numpy as np
from scipy import stats

EDGES = [560.0, 630.0, 690.0, 750.0, 820.0]
INF = 1e12


def em_gmm(X, K=4, iters=400, seed=0):
    rng = np.random.default_rng(seed)
    mu = np.quantile(X, (np.arange(K) + 0.5) / K)
    var = np.full(K, max(X.var(), 1.0))
    w = np.full(K, 1.0 / K)
    for _ in range(iters):
        d2 = (X[:, None] - mu[None, :]) ** 2 / var[None, :]
        logp = -0.5 * d2 + np.log(w + 1e-300) - 0.5 * np.log(2 * np.pi * var)
        mx = logp.max(1, keepdims=True)
        lse = mx[:, 0] + np.log(np.exp(logp - mx).sum(1))
        r = np.exp(logp - lse[:, None])
        Nk = r.sum(0) + 1e-12
        w = Nk / len(X)
        mu = (r * X[:, None]).sum(0) / Nk
        var = np.maximum((r * (X[:, None] - mu[None, :]) ** 2).sum(0) / Nk, 1e-4)
    return w, mu, var


def gmm_pdf(x, w, mu, var):
    x = np.asarray(x, dtype=float)
    out = np.zeros_like(x)
    for wi, mi, vi in zip(w, mu, var):
        out += wi * np.exp(-0.5 * (x - mi) ** 2 / vi) / np.sqrt(2 * np.pi * vi)
    return out


def gmm_cdf(x, w, mu, var):
    from scipy.stats import norm
    x = np.asarray(x, dtype=float)
    out = np.zeros_like(x)
    for wi, mi, vi in zip(w, mu, var):
        out += wi * norm.cdf(x, mi, np.sqrt(vi))
    return out


class KindModel:
    def __init__(self, K=4):
        self.K = K

    def fit(self, cells, priors, n_iter=30, seed=0):
        """cells: dict seg -> np.array(scores). priors: dict seg -> prob."""
        segs = list(cells)
        loc = {s: float(np.median(cells[s])) for s in segs}
        X = np.concatenate([cells[s] - loc[s] for s in segs])
        w, mu, var = em_gmm(X, K=self.K, seed=seed)
        p = np.array([priors[s] for s in segs])
        for it in range(n_iter):
            # E-step: responsibilities over segments for each draw
            resp = {}
            newloc = {}
            for s in segs:
                x = cells[s]
                ll = np.array([np.log(max(p[t], 1e-300)) + np.log(np.maximum(gmm_pdf(x - loc[t], w, mu, var), 1e-300))
                               for t in segs])  # (seg, draw)
                mx = ll.max(0, keepdims=True)
                lse = mx + np.log(np.exp(ll - mx).sum(0, keepdims=True))
                r = np.exp(ll - lse)
                resp[s] = r
                nk = r.sum(1) + 1e-12
                newloc[s] = float((r * x[None, :]).sum(1) / nk)
            # M-step: update noise model with weighted residuals
            res_all, wts = [], []
            for si, s in enumerate(segs):
                r = resp[s]  # (seg, draw)
                for ti, t in enumerate(segs):
                    res_all.append(cells[t] - newloc[t])
                    wts.append(r[ti])
            R = np.concatenate(res_all)
            W = np.concatenate(wts)
            # weighted EM
            rng = np.random.default_rng(seed + it)
            mu = np.quantile(R, (np.arange(self.K) + 0.5) / self.K)
            var = np.full(self.K, max(R.var(), 1.0))
            ww = np.full(self.K, 1.0 / self.K)
            for _ in range(300):
                d2 = (R[:, None] - mu[None, :]) ** 2 / var[None, :]
                logp = -0.5 * d2 + np.log(ww + 1e-300) - 0.5 * np.log(2 * np.pi * var)
                mx = logp.max(1, keepdims=True)
                lse = mx + np.log(np.exp(logp - mx).sum(1))
                r = np.exp(logp - lse[:, None]) * W[:, None]
                Nk = r.sum(0) + 1e-12
                ww = Nk / W.sum()
                mu = (r * R[:, None]).sum(0) / Nk
                var = np.maximum((r * (R[:, None] - mu[None, :]) ** 2).sum(0) / Nk, 1e-4)
            w, mu, var = ww, mu, var
            loc = newloc
        self.loc, self.w, self.mu, self.var = loc, w, mu, var
        return self

    def band_probs(self, seg):
        cdfs = [gmm_cdf(np.array([-INF] + EDGES + [INF]), self.w, self.mu, self.var)]
        f = cdfs[0]
        probs = np.diff(f)
        return probs

    def table(self, segs):
        return {s: self.band_probs(s) for s in segs}


if __name__ == "__main__":
