        print(c, "locs:", {s: round(m.loc[s], 1) for s in cells})
        print("  gmm w:", np.round(m.w, 3), "mu:", np.round(m.mu, 1), "sd:", np.round(np.sqrt(m.var), 1))
        for s in cells:
            emp = np.zeros(6)
            x = cells[s]
