#!/usr/bin/env python3
"""Model: per (segment, check) band probability tables.
Fits per-check-kind noise density (GMM) + per-cell locations via EM."""
import json
import numpy as np
from scipy.stats import norm

EDGES = np.array([560.0, 630.0, 690.0, 750.0, 820.0])
BOUNDS = np.array([-np.inf] + list(EDGES) + [np.inf])
SEGS = ["S1", "S2", "S3", "S4", "S5", "S6"]
CHECKS = ["bureau", "income", "bank"]


def gmm_logpdf(x, w, mu, var):
    d2 = (x[..., None] - mu) ** 2 / var
    lp = -0.5 * d2 - 0.5 * np.log(2 * np.pi * var) + np.log(w + 1e-300)
    mx = lp.max(-1, keepdims=True)
    return (mx + np.log(np.exp(lp - mx).sum(-1, keepdims=True)))[..., 0]


def gmm_cdf(x, w, mu, var):
    out = np.zeros_like(np.asarray(x, dtype=float))
    for wi, mi, vi in zip(w, mu, var):
        out += wi * norm.cdf(x, mi, np.sqrt(vi))
    return out


def em_gmm(X, K, w0=None, iters=500):
    n = len(X)
    if w0 is None:
        w = np.full(K, 1.0 / K)
    else:
        w = np.array(w0, dtype=float)
    mu = np.quantile(X, (np.arange(K) + 0.5) / K)
    var = np.full(K, max(X.var(), 1.0))
    for _ in range(iters):
        d2 = (X[:, None] - mu[None, :]) ** 2 / var[None, :]
        lp = -0.5 * d2 + np.log(w + 1e-300) - 0.5 * np.log(2 * np.pi * var)
        mx = lp.max(1, keepdims=True)
        lse = mx[:, 0] + np.log(np.exp(lp - mx).sum(1))
        r = np.exp(lp - lse[:, None])
        Nk = r.sum(0) + 1e-12
        w = Nk / n
        mu = (r * X[:, None]).sum(0) / Nk
        var = np.maximum((r * (X[:, None] - mu[None, :]) ** 2).sum(0) / Nk, 1e-3)
    return w, mu, var


class KindModel:
    """score = loc[seg] + noise, noise ~ GMM shared across segments."""

    def __init__(self, K=3, n_iter=25):
        self.K = K
        self.n_iter = n_iter

    def fit(self, cells, priors, var_floor=20.0):
        segs = [s for s in SEGS if s in cells and len(cells[s]) > 0]
        loc = {s: float(np.median(cells[s])) for s in segs}
        X = np.concatenate([cells[s] - loc[s] for s in segs])
        w, mu, var = em_gmm(X, self.K)
        var = np.maximum(var, var_floor ** 2)
        p = {s: priors[s] for s in segs}
        for it in range(self.n_iter):
            num = {s: 0.0 for s in segs}
            den = {s: 0.0 for s in segs}
            resid, wt = [], []
            for s in segs:
                x = cells[s]
                ll = np.stack([np.log(max(p[t], 1e-300))
                               + gmm_logpdf(x - loc[t], w, mu, var) for t in segs])
                mx = ll.max(0, keepdims=True)
                lse = mx[:, 0] + np.log(np.exp(ll - mx).sum(0))
                r = np.exp(ll - lse)
                for ti, t in enumerate(segs):
                    num[t] += float((r[ti] * x).sum())
                    den[t] += float(r[ti].sum())
            newloc = {t: num[t] / max(den[t], 1e-12) for t in segs}
            for s in segs:
                x = cells[s]
                ll = np.stack([np.log(max(p[t], 1e-300))
                               + gmm_logpdf(x - loc[t], w, mu, var) for t in segs])
                mx = ll.max(0, keepdims=True)
                lse = mx[:, 0] + np.log(np.exp(ll - mx).sum(0))
                r = np.exp(ll - lse)
                for ti, t in enumerate(segs):
                    resid.append(x - newloc[t])
                    wt.append(r[ti])
            R = np.concatenate(resid)
            W = np.concatenate(wt)
            # weighted EM for the mixture
            K = self.K
            w = np.full(K, 1.0 / K)
            mu = np.quantile(R, (np.arange(K) + 0.5) / K)
            var = np.maximum(np.full(K, max(R.var(), 1.0)), var_floor ** 2)
            for _ in range(400):
                d2 = (R[:, None] - mu[None, :]) ** 2 / var[None, :]
                lp = -0.5 * d2 + np.log(w + 1e-300) - 0.5 * np.log(2 * np.pi * var)
                mx = lp.max(1, keepdims=True)
                lse = mx[:, 0] + np.log(np.exp(lp - mx).sum(1))
                r = np.exp(lp - lse[:, None]) * W[:, None]
                Nk = r.sum(0) + 1e-12
                w = Nk / W.sum()
                mu = (r * R[:, None]).sum(0) / Nk
                var = np.maximum((r * (R[:, None] - mu[None, :]) ** 2).sum(0) / Nk, var_floor ** 2)
            loc = newloc
        self.loc, self.w, self.mu, self.var = loc, w, mu, var
        self.segs = segs
        return self

    def band_probs(self, seg):
        f = gmm_cdf(BOUNDS - self.loc[seg], self.w, self.mu, self.var)
        return np.diff(f)

    def table(self):
        return {s: self.band_probs(s) for s in self.segs}


if __name__ == "__main__":
    import sys
    d = json.load(open("/tmp/opencode/data.json"))
    K = int(sys.argv[1]) if len(sys.argv) > 1 else 3
    models = {}
    for c in CHECKS:
