#!/usr/bin/env python3
"""Policy evaluation + model-error sensitivity analysis."""
import json
import numpy as np
from decision import (SEGS, EV, CHECKS, CHECK_COST, Decision, band_table_from_model,
                      load_priors, MAX_CHECKS)


def solve_policies(bp, priors, L=4):
    dec = Decision(bp)
    pols = []
    for pr in priors:
        v, memo = dec.solve(pr, max_checks=L)
        pols.append(memo)
    return pols


def eval_policies(pols, bp_truth, priors, n=20000, seed=0, verbose=False):
    """MC: follow policy, truth model bp_truth. Returns total expected net value."""
    rng = np.random.default_rng(seed)
    arrs = {k: np.array([bp_truth[k][s] for s in SEGS]) for k in CHECKS}
    total = 0.0
    details = []
    for i, pr in enumerate(priors):
        pv = np.array([pr[s] for s in SEGS])
        memo = pols[i]
        seg_draw = rng.choice(6, size=n, p=pv)
        state = ()
        payoff = np.zeros(n)
        cost = 0.0
        active = np.ones(n, dtype=bool)
        # process step by step (states differ across sims -> group)
        cur_states = [()] * n
        done = np.zeros(n, dtype=bool)
        for step in range(MAX_CHECKS):
            # group by state
            groups = {}
            for j in range(n):
                if done[j]:
                    continue
                groups.setdefault(cur_states[j], []).append(j)
            for st, idxs in groups.items():
                act = memo.get(st, (0.0, ("decline", None)))[1]
                if act[0] == "decline":
                    done[idxs] = True
                elif act[0] == "approve":
                    p = np.zeros(6)
                    lw = np.log(np.maximum(pv, 1e-300))
                    for ki, b in st:
                        lw = lw + np.log(np.maximum(arrs[CHECKS[ki]][:, b], 1e-300))
                    w = np.exp(lw - lw.max())
                    p = w / w.sum()
                    payoff[idxs] += p @ EV
                    done[idxs] = True
                else:
                    kind = act[1]
                    ki = CHECKS.index(kind)
                    for j in idxs:
                        b = rng.choice(6, p=arrs[kind][seg_draw[j]])
                        cur_states[j] = tuple(sorted(cur_states[j] + ((ki, b),)))
                    cost += 20.0 * len(idxs)
        total += payoff.mean() - cost
        details.append((i + 1, payoff.mean(), cost))
    if verbose:
        for i, p, c in details:
            print(f"  app {i:2d}: payoff={p:8.2f} cost={c:7.2f} net={p-c:8.2f}")
    return total


def perturb_model(model, sigma, rng):
    """Perturb cell locations (and optionally mixture params) to create an alternative truth."""
    out = {}
    for c, m in model.items():
        mm = {k: (list(v) if isinstance(v, list) else dict(v)) for k, v in m.items()}
        mm["loc"] = {s: loc + rng.normal(0, sigma) for s, loc in m["loc"].items()}
        out[c] = mm
    return out


if __name__ == "__main__":
    model = json.load(open("/tmp/opencode/model.json"))
    bp = {c: band_table_from_model(m) for c, m in model.items()}
    priors = load_priors()
    for L in [3, 4]:
        pols = solve_policies(bp, priors, L=L)
        base = eval_policies(pols, bp, priors, n=4000, seed=1)
        print(f"L={L}: policy(M0) under M0 = {base:.1f}", flush=True)
        # regret under perturbed truths
        for sigma in [5, 10, 20, 40]:
            regs = []
            for rep in range(3):
                rng = np.random.default_rng(100 + rep)
                pm = perturb_model(model, sigma, rng)
                bpt = {c: band_table_from_model(m) for c, m in pm.items()}
                v_under = eval_policies(pols, bpt, priors, n=3000, seed=7 + rep)
                # optimal under truth
                opt_pol = solve_policies(bpt, priors, L=L)
                opt_v = eval_policies(opt_pol, bpt, priors, n=3000, seed=7 + rep)
                regs.append(v_under - opt_v)
            print(f"   sigma={sigma:3d}: regret = {np.mean(regs):8.1f} (+-{np.std(regs):.1f})", flush=True)

#!/usr/bin/env python3
"""Robust Student-t noise model per check kind + per-cell locations, with bootstrap SEs."""
import json
import numpy as np
from scipy import stats
from scipy.optimize import minimize

EDGES = np.array([560.0, 630.0, 690.0, 750.0, 820.0])
BOUNDS = np.array([-np.inf] + list(EDGES) + [np.inf])
SEGS = ["S1", "S2", "S3", "S4", "S5", "S6"]
CHECKS = ["bureau", "income", "bank"]


def fit_t(X, nu0=2.0):
    """MLE of (nu, scale) for centered data X."""
    def nll(par):
        nu, sc = np.exp(par[0]), np.exp(par[1])
        sc = max(sc, 1.0)
        return -stats.t.logpdf(X / sc, nu).sum() + len(X) * np.log(sc)
    r = minimize(nll, [np.log(nu0), np.log(max(np.median(np.abs(X)) * 1.4826, 5.0))],
                 method="Nelder-Mead", options={"maxiter": 2000, "xatol": 1e-4, "fatol": 1e-4})
    nu, sc = np.exp(r.x[0]), np.exp(r.x[1])
    return nu, sc


class TModel:
    """score = loc[seg] + noise, noise ~ Student-t(nu, 0, scale)."""

    def __init__(self, n_iter=12):
        self.n_iter = n_iter

    def fit(self, cells, floor_scale=5.0):
        segs = [s for s in SEGS if s in cells and len(cells[s]) > 0]
        loc = {s: float(np.median(cells[s])) for s in segs}
        R = np.concatenate([cells[s] - loc[s] for s in segs])
        nu, sc = fit_t(R)
        for it in range(self.n_iter):
            # per-cell robust location (independent per cell)
            for s in segs:
                x = cells[s]
                r = x - loc[s]
                u = (nu + 1.0) / (nu + (r / sc) ** 2)
                loc[s] = float((u * x).sum() / max(u.sum(), 1e-12))
            R = np.concatenate([cells[s] - loc[s] for s in segs])
            nu, sc = fit_t(R)
            sc = max(sc, floor_scale)
        self.loc, self.nu, self.scale = loc, nu, sc
        self.segs = segs
        return self

    def band_probs(self, seg):
        x = BOUNDS - self.loc[seg]
        f = stats.t.cdf(x, self.nu, 0, self.scale)
        return np.diff(f)

    def table(self):
        return {s: self.band_probs(s) for s in self.segs}

    def to_json(self):
        return {"loc": self.loc, "nu": self.nu, "scale": self.scale}


def load_cells(path="/tmp/opencode/data.json"):
    d = json.load(open(path))
    out = {}
    for c in CHECKS:
        cells = {}
        for s in SEGS:
            v = np.array(d.get(f"{c}|{s}", []), dtype=float)
            if len(v):
                cells[s] = v
        out[c] = cells
    return out


if __name__ == "__main__":
    import sys
    cells = load_cells()
    rng = np.random.default_rng(0)
    reps = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    for c in CHECKS:
        m = TModel().fit(cells[c])
        print("=" * 72)
        print(f"{c}: nu={m.nu:.2f} scale={m.scale:.1f}")
        for s in m.segs:
            emp = np.zeros(6)
            for val in cells[c][s]:
                emp[np.searchsorted(EDGES, val)] += 1
            emp /= len(cells[c][s])
            print(f"  {s} loc={m.loc[s]:7.1f} model={np.round(m.band_probs(s),3)} emp={np.round(emp,3)}")
        if reps:
            boots = {s: [] for s in m.segs}
            for b in range(reps):
                bc = {s: rng.choice(cells[c][s], size=len(cells[c][s]), replace=True) for s in m.segs}
                mb = TModel().fit(bc)
                for s in m.segs:
                    boots[s].append(mb.loc[s])
            for s in m.segs:
                a = np.array(boots[s])
                print(f"    {s} loc SE={a.std(ddof=1):5.1f}  mean={a.mean():7.1f} (point {m.loc[s]:.1f})")

#!/usr/bin/env python3
"""Exact evaluation of a fixed policy under a given truth model (forward propagation)."""
import numpy as np
from decision import SEGS, EV, CHECKS, CHECK_COST, MAX_CHECKS


def eval_policy_exact(policy, bp_truth, prior, max_checks=MAX_CHECKS):
    """policy: dict state(tuple of (kind_idx,band)) -> (value, action)
    Returns expected net value of following `policy` under truth `bp_truth`."""
    arrs = {k: np.array([bp_truth[k][s] for s in SEGS]) for k in CHECKS}
    prior_vec = np.array([prior[s] for s in SEGS])
    # forward propagation over states
    mass = {(): 1.0}
    expected = 0.0
    for depth in range(max_checks + 1):
        newmass = {}
        for st, m in mass.items():
            if m <= 1e-15:
                continue
            act = policy.get(st, (0.0, ("decline", None)))[1]
            if act[0] == "decline":
                continue
            if act[0] == "approve":
                lw = np.log(np.maximum(prior_vec, 1e-300))
                for ki, b in st:
                    lw = lw + np.log(np.maximum(arrs[CHECKS[ki]][:, b], 1e-300))
                w = np.exp(lw - lw.max())
                p = w / w.sum()
                expected += m * float(p @ EV)
                continue
            # check action
            kind = act[1]
            ki = CHECKS.index(kind)
            q = arrs[kind]
            # predictive over bands given current posterior
            lw = np.log(np.maximum(prior_vec, 1e-300))
            for kj, b in st:
                lw = lw + np.log(np.maximum(arrs[CHECKS[kj]][:, b], 1e-300))
            w = np.exp(lw - lw.max())
            post = w / w.sum()
            pred = q.T @ post
            expected -= m * CHECK_COST
            for b in range(6):
                if pred[b] <= 1e-15:
                    continue
                nst = tuple(sorted(st + ((ki, b),)))
                newmass[nst] = newmass.get(nst, 0.0) + m * pred[b]
        mass = newmass
        if not mass:
            break
    return expected

#!/usr/bin/env python3
"""Build candidate models from existing sandbox data; cross-evaluate robustness."""
import json
import numpy as np
from scipy import stats
from decision import (SEGS, EV, CHECKS, Decision, band_table_from_model, load_priors,
                      MAX_CHECKS)
from exact_eval import eval_policy_exact
from tmodel import TModel, EDGES, load_cells
from model import KindModel

CELLS = load_cells()


def emp_tables(cells):
    out = {}
    for c, cs in cells.items():
        d = {}
        for s, v in cs.items():
            cnt = np.zeros(6)
            for val in v:
                cnt[np.searchsorted(EDGES, val)] += 1
            d[s] = cnt / len(v)
        out[c] = d
    return out


def build_candidates():
    cands = {}
    # M1: GMM-EM
    m1 = {}
    for c, cs in CELLS.items():
        m1[c] = KindModel(K=3).fit(cs, {s: 1 / 6 for s in cs})
    cands["gmm"] = {c: m.table() for c, m in m1.items()}
    # M2: Student-t
    m2 = {}
    for c, cs in CELLS.items():
        m2[c] = TModel().fit(cs)
    cands["t"] = {c: m.table() for c, m in m2.items()}
    # M3: direct empirical (Laplace smoothed)
    e = emp_tables(CELLS)
    cands["emp"] = {c: {s: (v * len(CELLS[c][s]) + 0.5) / (len(CELLS[c][s]) + 3.0)
                        for s, v in e[c].items()} for c in e}
    # M4: shrinkage blend emp + model(avg of gmm,t)
    for kappa in (10, 20, 40):
        blend = {}
        for c in CHECKS:
            avg = {s: 0.5 * (cands["gmm"][c][s] + cands["t"][c][s]) for s in cands["gmm"][c]}
            blend[c] = {}
            for s in avg:
                n = len(CELLS[c][s])
                cnt = e[c][s] * n
                blend[c][s] = (cnt + kappa * avg[s]) / (n + kappa)
        cands[f"blend{kappa}"] = blend
    return cands


def solve_all(bp, priors, L=4):
    dec = Decision(bp)
    pols, vals = [], []
    for pr in priors:
        v, memo = dec.solve(pr, max_checks=L)
        pols.append(memo)
        vals.append(v)
    return pols, vals


if __name__ == "__main__":
    priors = load_priors()
    cands = build_candidates()
    names = list(cands)
    print("DP values under each candidate model (L=4):")
    for n in names:
        _, vals = solve_all(cands[n], priors, L=4)
        print(f"  {n:9s}: total={sum(vals):8.1f}")
    print()
    print("Cross-regret: policy from row model, truth = column model (sum over 20 applicants)")
    pols = {n: solve_all(cands[n], priors, L=4)[0] for n in names}
    hdr = "policy\\truth " + "".join(f"{n:>10s}" for n in names)
    print(hdr)
    for a in names:
        row = []
        for b in names:
            tot = 0.0
            for i, pr in enumerate(priors):
                tot += eval_policy_exact(pols[a][i], cands[b], pr)
            opt = sum(solve_all(cands[b], priors, L=4)[1])
            row.append(tot - opt)
        print(f"{a:9s}: " + "".join(f"{v:10.1f}" for v in row))
